#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "h3api.h"
#include "utility.h"

static const Direction DIGITS[7] = {CENTER_DIGIT,  K_AXES_DIGIT, J_AXES_DIGIT,
                                    JK_AXES_DIGIT, I_AXES_DIGIT, IK_AXES_DIGIT,
                                    IJ_AXES_DIGIT};

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  char *new_str = (char *)malloc(size + 1);
  if (new_str == NULL) {
    return 0;
  }
  memcpy(new_str, data, size);
  new_str[size] = '\0';

  H3Index h3;
  h3 = H3_EXPORT(stringToH3)(new_str);

  H3Index input[] = {h3, h3};
  int inputSize = sizeof(input) / sizeof(H3Index);

  // fuzz compactCells
  H3Index *compacted = calloc(inputSize, sizeof(H3Index));
  int err = compactCells(input, compacted, inputSize);

  // fuzz uncompactCells
  int compactedCount = 0;
  for (int i = 0; i < inputSize; i++) {
    if (compacted[i] != 0) {
      compactedCount++;
    }
  }
  if (compactedCount < 2) {
    int uncompactRes = 10;
    int64_t uncompactedSize;
    H3Error err2 =
        uncompactCellsSize(compacted, inputSize, uncompactRes, &uncompactedSize);

    H3Index *uncompacted = calloc(uncompactedSize, sizeof(H3Index));
    int err3 = uncompactCells(compacted, compactedCount, uncompacted,
                              uncompactedSize, uncompactRes);
    free(uncompacted);
  }

  // fuzz h3NeighborRotations
  int rotations = 0;
  for (int i = 0; i < 7; i++) {
    h3NeighborRotations(h3, DIGITS[i], &rotations);
  }
  free(compacted);
  free(new_str);
  return 0;
}
